$ErrorActionPreference='Stop';Add-Type -AssemblyName System.Security;Add-Type -AssemblyName System.Data
$root=Split-Path -Parent (Split-Path -Parent $PSScriptRoot);$cfg=Join-Path $root 'LavaFacil.Web\Data\connection.dpapi';$raw=[Security.Cryptography.ProtectedData]::Unprotect([IO.File]::ReadAllBytes($cfg),$null,[Security.Cryptography.DataProtectionScope]::CurrentUser);$saved=[Text.Encoding]::UTF8.GetString($raw).Replace('Trust Server Certificate','TrustServerCertificate').Replace('Encrypt=Mandatory','Encrypt=True');$c=New-Object System.Data.SqlClient.SqlConnection((New-Object System.Data.SqlClient.SqlConnectionStringBuilder $saved).ConnectionString);$c.Open();$q=$c.CreateCommand();$q.CommandText="SELECT (SELECT COUNT(*) FROM dbo.Usuarios WHERE NombreUsuario LIKE 'autotest.%') U,(SELECT COUNT(*) FROM dbo.Clientes WHERE Email LIKE 'autotest.%') C,(SELECT COUNT(*) FROM dbo.TokensCorreo WHERE IdUsuario NOT IN (SELECT IdUsuario FROM dbo.Usuarios)) T";$r=$q.ExecuteReader();$r.Read();$u=$r.GetInt32(0);$cl=$r.GetInt32(1);$t=$r.GetInt32(2);$r.Close();$c.Dispose();$outbox=Join-Path $env:TEMP 'opencode\lavafacil-mail-outbox';$eml=@(Get-ChildItem $outbox -Filter *.eml -ErrorAction SilentlyContinue).Count;$lava=@(Get-Process -Name LavaFacil.Web -ErrorAction SilentlyContinue).Count;$dotnet=@(Get-Process -Name dotnet -ErrorAction SilentlyContinue).Count;$p5088=@(Get-NetTCPConnection -LocalPort 5088 -State Listen -ErrorAction SilentlyContinue).Count;$p5089=@(Get-NetTCPConnection -LocalPort 5089 -State Listen -ErrorAction SilentlyContinue).Count;[pscustomobject]@{usuarios=$u;clientes=$cl;tokensHuerfanos=$t;eml=$eml;procesosLavaFacil=$lava;procesosDotnet=$dotnet;puerto5088=$p5088;puerto5089=$p5089}|ConvertTo-Json
